import{_ as a,o as e,c as r,ag as i}from"./chunks/framework.C9sp7nFj.js";const m=JSON.parse('{"title":"SetSimDOByVar 按变量设置虚拟数字量输出","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/SetSimDOByVar.md","filePath":"3. 指令/4. IO 指令/SetSimDOByVar.md","lastUpdated":1778862643000}'),d={name:"3. 指令/4. IO 指令/SetSimDOByVar.md"};function s(o,t,n,h,l,c){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="setsimdobyvar-按变量设置虚拟数字量输出" tabindex="-1">SetSimDOByVar 按变量设置虚拟数字量输出 <a class="header-anchor" href="#setsimdobyvar-按变量设置虚拟数字量输出" aria-label="Permalink to &quot;SetSimDOByVar 按变量设置虚拟数字量输出&quot;">​</a></h1><p>该指令用于将某个布尔型变量（BOOL）的值映射到一个虚拟数字量输出（SimDO）端口上。它是 <code>GetSimDIToVar</code> 的反向操作，常用于将程序内部计算逻辑的结果通过虚拟端口输出，以便其他监控程序或后台逻辑读取。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>SetSimDOByVar (SIMDOUT, VAR)</code></p><p><code>SetSimDOByVar (虚拟数字量输出口, 变量)</code></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>SIMDOUT</td><td>SimDO</td><td>将获取到的变量值在该变量绑定的 SimDO 端口进行状态输出</td><td>必填</td></tr><tr><td>VAR</td><td>BOOL</td><td>获取该布尔变量的值（TRUE 或 FALSE），并输出给指定的虚拟数字量输出端口</td><td>必填</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetSimDOByVar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (SimDO9, BOOL1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>将变量 <strong>BOOL1</strong> 的状态在虚拟数字量变量 <strong>SimDO9</strong> 对应端口输出。若 <code>BOOL1</code> 为 TRUE，则 <code>SimDO9</code> 状态变为 1；若为 FALSE，则状态变为 0。</p>',13)])])}const S=a(d,[["render",s]]);export{m as __pageData,S as default};
